package dev.raven.backup;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.DocumentsContract;import org.json.*;import java.io.*;import java.util.*;
/** Deletes reviewed ZIPs or empties a reviewed folder without deleting the selected root. */
final class BackupStorage {
 static final class PurgeItem {Uri uri;String id,parent,name,path,mime;long bytes,modified;boolean folder;}
 static final class PurgePlan {Uri tree;List<PurgeItem> items=new ArrayList<>();int files,folders;long bytes;}
 static PurgePlan reviewPurge(Context c,Uri tree)throws Exception{if(tree==null)throw new IOException("Choose a backup folder first");PurgePlan plan=new PurgePlan();plan.tree=tree;scanPurge(c,plan,DocumentsContract.getTreeDocumentId(tree),"",0,new HashSet<>());return plan;}
 static void scanPurge(Context c,PurgePlan plan,String parent,String prefix,int depth,Set<String> seen)throws Exception{if(depth>32||seen.size()>10000||plan.items.size()>10000)throw new IOException("Backup folder is too large to review safely; choose a smaller folder");if(!seen.add(parent))throw new IOException("Storage returned a repeated folder; purge stopped");List<PurgeItem> children=new ArrayList<>();String[] columns={DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_SIZE,DocumentsContract.Document.COLUMN_LAST_MODIFIED,DocumentsContract.Document.COLUMN_MIME_TYPE};try(Cursor rows=c.getContentResolver().query(DocumentsContract.buildChildDocumentsUriUsingTree(plan.tree,parent),columns,null,null,null)){if(rows==null)throw new IOException("Cannot read backup folder");while(rows.moveToNext()){PurgeItem item=new PurgeItem();item.id=rows.getString(0);item.parent=parent;item.name=rows.getString(1);item.path=prefix+item.name;item.bytes=rows.getLong(2);item.modified=rows.getLong(3);item.mime=rows.getString(4);item.folder=DocumentsContract.Document.MIME_TYPE_DIR.equals(item.mime);item.uri=DocumentsContract.buildDocumentUriUsingTree(plan.tree,item.id);children.add(item);if(children.size()+plan.items.size()>10000)throw new IOException("Too many items to review safely");}}children.sort((a,b)->a.path.compareTo(b.path));for(PurgeItem item:children){if(item.folder){scanPurge(c,plan,item.id,item.path+"/",depth+1,seen);plan.folders++;}else{plan.files++;plan.bytes+=item.bytes;}plan.items.add(item);}}
 static Map<String,String> snapshot(PurgePlan plan){Map<String,String> values=new HashMap<>();for(PurgeItem item:plan.items)values.put(item.id,item.parent+"\n"+item.name+"\n"+item.mime+"\n"+(item.folder?"folder":item.bytes+":"+item.modified));return values;}
 static void purgeAllowed(Context c,PurgePlan plan,PurgeItem item)throws Exception{String rootId=DocumentsContract.getTreeDocumentId(plan.tree);Uri root=DocumentsContract.buildDocumentUriUsingTree(plan.tree,rootId);if(rootId.equals(item.id)||!rootId.equals(DocumentsContract.getTreeDocumentId(item.uri))||!DocumentsContract.isChildDocument(c.getContentResolver(),root,item.uri))throw new IOException("Item is outside the chosen backup folder: "+item.path);String[] columns={DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE,DocumentsContract.Document.COLUMN_LAST_MODIFIED,DocumentsContract.Document.COLUMN_FLAGS};try(Cursor row=c.getContentResolver().query(item.uri,columns,null,null,null)){if(row==null||!row.moveToFirst()||!item.name.equals(row.getString(0))||!item.mime.equals(row.getString(1))||(!item.folder&&(item.bytes!=row.getLong(2)||item.modified!=row.getLong(3))))throw new IOException("Contents changed; review again: "+item.path);if((row.getInt(4)&DocumentsContract.Document.FLAG_SUPPORTS_DELETE)==0)throw new IOException("Storage cannot delete "+item.path);}}
 static boolean empty(Context c,Uri tree,String id)throws Exception{try(Cursor rows=c.getContentResolver().query(DocumentsContract.buildChildDocumentsUriUsingTree(tree,id),new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID},null,null,null)){if(rows==null)throw new IOException("Cannot verify empty folder");return !rows.moveToFirst();}}
 static String purge(Context c,PurgePlan plan)throws Exception{synchronized(LiveRestore.class){if(new File(c.getFilesDir(),"live-pending.json").exists())throw new IOException("Recover the pending restore before purging");PurgePlan fresh=reviewPurge(c,plan.tree);if(!snapshot(plan).equals(snapshot(fresh)))throw new IOException("Backup folder contents changed; review Purge again. Nothing was removed.");for(PurgeItem item:plan.items)purgeAllowed(c,plan,item);int removed=0;try{for(PurgeItem item:plan.items){purgeAllowed(c,plan,item);if(item.folder&&!empty(c,plan.tree,item.id))throw new IOException("New files appeared in "+item.path+"; review again");if(!DocumentsContract.deleteDocument(c.getContentResolver(),item.uri))throw new IOException("Storage refused deletion: "+item.path);removed++;}if(!empty(c,plan.tree,DocumentsContract.getTreeDocumentId(plan.tree)))throw new IOException("New items appeared in the backup folder; review again");}catch(Exception e){throw new IOException("Removed "+removed+" of "+plan.items.size()+" reviewed items. "+e.getMessage(),e);}return "Backup folder is empty. Removed "+plan.files+" files and "+plan.folders+" subfolders. The selected backup folder was kept. Installed app data was not changed.";}}
 static void allowed(Context c,Uri tree,BackupCatalog.Entry e)throws Exception{if(e.privateRecovery){RecoveryStore.allowed(c,e);return;}if(tree==null||!DocumentsContract.getTreeDocumentId(tree).equals(DocumentsContract.getTreeDocumentId(e.uri)))throw new IOException("Backup folder changed; review again");Uri root=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));if(!DocumentsContract.isChildDocument(c.getContentResolver(),root,e.uri))throw new IOException("ZIP is outside the chosen backup folder");String[] columns={DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_SIZE,DocumentsContract.Document.COLUMN_LAST_MODIFIED,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_FLAGS};try(Cursor row=c.getContentResolver().query(e.uri,columns,null,null,null)){if(row==null||!row.moveToFirst()||!e.name.equals(row.getString(0))||e.size!=row.getLong(1)||e.modified!=row.getLong(2)||DocumentsContract.Document.MIME_TYPE_DIR.equals(row.getString(3)))throw new IOException("Backup changed; refresh and review again: "+e.name);if((row.getInt(4)&DocumentsContract.Document.FLAG_SUPPORTS_DELETE)==0)throw new IOException("Storage cannot delete "+e.name);}}
 static String delete(Context c,Uri tree,List<BackupCatalog.Entry> entries)throws Exception{synchronized(LiveRestore.class){if(entries.isEmpty())throw new IOException("No backups selected");if(new File(c.getFilesDir(),"live-pending.json").exists())throw new IOException("Recover the pending restore before deleting backups");Set<String> seen=new HashSet<>();for(BackupCatalog.Entry e:entries){if(!seen.add(e.uri.toString())||!e.name.toLowerCase(Locale.ROOT).endsWith(".zip"))throw new IOException("Invalid ZIP selection");allowed(c,tree,e);}int deleted=0;try{for(BackupCatalog.Entry e:entries){allowed(c,tree,e);if(e.privateRecovery)RecoveryStore.delete(c,e);else if(!DocumentsContract.deleteDocument(c.getContentResolver(),e.uri))throw new IOException("Storage refused deletion: "+e.name);deleted++;}}catch(Exception e){throw new IOException("Deleted "+deleted+" of "+entries.size()+" ZIPs. "+e.getMessage(),e);}return "Deleted "+deleted+" backup ZIPs. App data and other files were not changed.";}}
}
